def build_prompt(ticket, examples):
    parts = ["You label support tickets.",
             "One word: billing, bug, other."]
    for text, label in examples:
        parts.append(f"Ticket: {text}")
        parts.append(f"Label: {label}")
    parts.append(f"Ticket: {ticket}")
    parts.append("Label:")
    return "\n".join(parts)
